#car{display:block!important;top:-34px;color:#ef2924}#car svg{overflow:visible}#current-year{background:transparent!important;padding:0;top:-30px;margin-left:-52px;transform:translateX(-100%);font-size:18px;color:#444;white-space:nowrap}.dark #current-year{color:#ddd}#bottom{z-index:10}#mural{display:none!important}.full-mural #pictures [data-image="full"],.full-mural #ghosts{opacity:initial!important}#stage image:focus{outline:none}#chapter-cover{position:fixed;inset:0;z-index:60;background:#151515;display:grid;grid-template-columns:repeat(5,1fr);gap:3px;padding:4vh 3vw;overflow:hidden}#chapter-cover[hidden]{display:none}.chapter-strip{position:relative;overflow:hidden;border:0;padding:0;background:#222;color:white;cursor:pointer;height:88vh;align-self:center;transition:transform .7s,opacity .7s;transition-delay:calc(var(--i)*100ms)}.chapter-strip:nth-child(2),.chapter-strip:nth-child(4){height:94vh}.chapter-strip img{position:absolute;max-width:none;width:94vw;height:100%;left:calc(var(--i)*-18.8vw);top:0;object-fit:cover;object-position:center;filter:grayscale(1);transition:filter .45s}.chapter-strip:hover img,.chapter-strip:focus-visible img{filter:grayscale(0)}.chapter-strip span{position:absolute;bottom:0;left:0;right:0;padding:40px 18px 24px;background:linear-gradient(transparent,rgba(0,0,0,.8));font:15px/1.7 sans-serif;letter-spacing:1px;text-align:left}.chapter-strip small{display:block;font:30px/1.8 Arial}.leaving .chapter-strip{transform:translateX(110vw);opacity:0}.in-directory{overflow:hidden}.in-directory #bottom,.in-directory #nodes,.in-directory #chapters,.in-directory #directory-return{visibility:hidden}#directory-return{position:fixed;top:24px;left:20px;background:transparent;color:#888;border:0;z-index:12;cursor:pointer;font-size:12px}#chapter-dialog{z-index:100}.ending #directory-return{display:none}

