/* Local revision: restrained paper and numeric chapter labels. */
body:before,#chapter-cover:before{opacity:.27}.chapter-strip span{left:auto;right:0;bottom:0;padding:12px 14px;background:none;text-align:right;letter-spacing:0;text-shadow:0 1px 5px #0008}.chapter-strip small{font:400 22px/1.2 Arial;color:#fff}#copy [data-scene="11"] text{font-family:KingHwaOldSong,serif}

#chapter-cover{animation:directory-fade13 .6s both}.chapter-strip{animation:strip-enter13 .9s cubic-bezier(.22,1,.36,1) calc(var(--i)*.12s) both;border-radius:5px}.chapter-strip span{display:none}#chapter-cover.leaving .chapter-strip{animation:strip-exit13 .7s cubic-bezier(.4,0,.8,.2) calc(var(--i)*.1s) both}.directory-heading13{position:absolute;top:28px;left:94px;color:#625e57}.directory-heading13 h1{font-size:20px;font-weight:400;margin:0 0 10px}.directory-heading13 p{font-size:12px;color:#8c877f}.directory-hint13{position:absolute;right:3vw;bottom:3vh;width:280px;opacity:0;transform:translateY(10px);transition:.3s;pointer-events:none}.directory-hint13.visible{opacity:1;transform:none}.directory-hint13 h2{font-size:16px;font-weight:400}.directory-hint13 p{font-size:13px;line-height:1.8;color:#777}.leaving .directory-heading13,.leaving .directory-hint13{opacity:0;transition:opacity .3s}@keyframes directory-fade13{from{opacity:0}to{opacity:1}}@keyframes strip-enter13{from{transform:translateY(110vh);opacity:0}to{transform:translateY(0);opacity:1}}@keyframes strip-exit13{from{transform:translateY(0);opacity:1}to{transform:translateY(-120vh);opacity:0}}@media(prefers-reduced-motion:reduce){.chapter-strip,#chapter-cover{animation:none!important}#chapter-cover.leaving .chapter-strip{opacity:0}}@media(max-width:700px){.directory-heading13{left:80px;right:15px}.directory-heading13 h1{font-size:15px}.directory-hint13{width:220px;bottom:1vh;background:#f7f6f2dc;padding:8px}}

/* Keep the story concealed while the directory fades into view. */
.in-directory #viewport,.in-directory #start-hint{visibility:hidden!important}
html.story-boot #chapter-cover{visibility:hidden}
#chapter-cover{animation:none}
#chapter-cover.leaving{background-color:transparent;transition:background-color .7s ease}
#chapter-cover.leaving:before{opacity:0;transition:opacity .7s ease}

#chapter-cover.text-leaving19 .directory-heading13,#chapter-cover.text-leaving19 .directory-hint13{opacity:0!important;transition:opacity .3s ease}
#chapter-cover.leaving{background-color:#f7f6f2!important}
.image-enter19 #copy,.image-enter19 #date,.image-enter19 #bottom,.image-enter19 #nodes,.image-enter19 #chapters,.image-enter19 #start-hint,.image-enter19 #ghosts{opacity:0!important;animation:none!important;pointer-events:none}
#copy,#date,#bottom,#nodes,#chapters,#start-hint{transition:opacity .5s ease}
.image-enter19{overflow:hidden}

/* Entry opacity is controlled by one animation, never a competing transition. */
#copy,#date,#bottom,#nodes,#chapters,#start-hint{transition:none!important;animation:none!important}
.in-directory #copy,.in-directory #date,.in-directory #ghosts{visibility:hidden}

/* Reserve the scrollbar lane throughout entry; fixed SVG never changes width. */
html{overflow-y:scroll;scrollbar-gutter:stable}
#chapter-cover.leaving .chapter-strip{animation-duration:.46s;animation-delay:calc(var(--i)*.05s)}
#chapter-cover.text-leaving19 .directory-heading13,#chapter-cover.text-leaving19 .directory-hint13{transition-duration:.18s}
#pictures{translate:0 0}
